using System;using System.Collections;using System.Reflection;using UnityEngine;
public sealed class NewShotContactProbe:MonoBehaviour {
 public PlayerSkills owner;public bool accepted;
 void OnCollisionEnter2D(Collision2D c){Observe(c);}void OnCollisionStay2D(Collision2D c){Observe(c);}
 void Observe(Collision2D c){if(c.collider.GetComponentInParent<PlayerSkills>()!=owner)return;for(int i=0;i<c.contactCount;i++){var p=c.GetContact(i);Vector2 n=p.normal;if(Vector2.Dot(n,GetComponent<Rigidbody2D>().position-p.point)<0)n=-n;accepted|=(bool)typeof(PlayerSkills).GetMethod("IsFootContact",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(owner,new object[]{c.collider,p.point,n});}}
}
public sealed class DoubleShotTests:MonoBehaviour {
