 object Field(PlayerSkills s,string n){return typeof(PlayerSkills).GetField(n,P).GetValue(s);}object Call(PlayerSkills s,string n,params object[] args){return typeof(PlayerSkills).GetMethod(n,P).Invoke(s,args);}
