 IEnumerator Scene(bool skills){DownPulse=false;FanAxis=ZhaoAxis=0;PlayerSkills.Enabled=skills;typeof(GameAIMod).GetMethod("StartGame",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{0});yield return new WaitForSeconds(.15f);pt=Type.GetType("PlayerController, Assembly-CSharp");fan=GameObject.Find("Fan").GetComponent(pt);zhao=GameObject.Find("Zhao").GetComponent(pt);fb=(Rigidbody2D)pt.GetField("rb").GetValue(fan);zb=(Rigidbody2D)pt.GetField("rb").GetValue(zhao);fs=fan.GetComponent<PlayerSkills>();zs=zhao.GetComponent<PlayerSkills>();fa=fan.GetComponent<Animator>();za=zhao.GetComponent<Animator>();ball=(FindObjectOfType(Type.GetType("Ball, Assembly-CSharp")) as Component).GetComponent<Rigidbody2D>();ball.position=new Vector2(0,40);ball.gravityScale=0;ball.velocity=Vector2.zero;}
