  Check(start>=0&&end>start,"native kick clip actually plays and finishes");Check(speed,"kick-only animation rate is correct skills="+skills+" backward="+backward);Check(Mathf.Abs(za.speed-1)<.01f,"after shot animation returns to normal speed");Check(maxError<.3f,"faster kick preserves skeleton joints");if(skills)Check(Fx(zs,8)>=0,"quick shot has its own skill animation");if(!backward){if(skills)quickKick=end-start;else classicKick=end-start;}Debug.Log("NEW SHOT skills="+skills+" back="+backward+" duration="+(end-start)+" joint="+maxError);
 }
 IEnumerator AirShot(){yield return Scene(true);pt.GetField("doJump").SetValue(zhao,true);PlayerSkills.SetAction(za,"Jump",zhao);PlayerSkills.SetAction(za,"Kick",zhao);yield return new WaitForSeconds(.1f);PlayerSkills.SetAction(za,"Kick",zhao);yield return new WaitForSeconds(.22f);float radius=ball.GetComponent<CircleCollider2D>().radius*Mathf.Abs(ball.transform.lossyScale.x),best=float.PositiveInfinity;BoxCollider2D limb=null;Vector2 point=Vector2.zero,n=Vector2.zero,pos=Vector2.zero;foreach(string name in new[]{"L_LowLeg","R_LowLeg"}){var c=zhao.transform.Find(name).GetComponent<BoxCollider2D>();foreach(float side in new[]{-1f,1f}){Vector2 cp=c.transform.TransformPoint(c.offset+new Vector2(side*c.size.x*.5f,-c.size.y*.3f));Vector2 cn=c.transform.TransformDirection(Vector2.right*side);Vector2 candidate=cp+cn*radius*.85f;if(candidate.x<best){best=candidate.x;limb=c;point=cp;n=cn;pos=candidate;}}}ball.position=pos;ball.velocity=limb.attachedRigidbody.GetPointVelocity(point)-n*2;Physics2D.SyncTransforms();var probe=ball.gameObject.AddComponent<NewShotContactProbe>();probe.owner=zs;for(int i=0;i<5;i++)yield return new WaitForFixedUpdate();Check(probe.accepted,"aerial strike makes a real instep contact");Check(Fx(zs,4)>=0,"double-tap aerial instep shot now triggers burst");Check(ball.velocity.x<-12&&ball.velocity.y<=.5f,"aerial burst remains fast and pressed low");Check(Fx(zs,8)>=0,"aerial shot still benefits from quicker swing");}
 IEnumerator GroundShot(){yield return Scene(true);ball.position=new Vector2(0,-1.55f);ball.gravityScale=1;ball.velocity=Vector2.zero;Physics2D.SyncTransforms();yield return new WaitForSeconds(.12f);Check(!(bool)Call(zs,"IsBallAirborne"),"ground burst begins with actual pitch contact");Check((bool)Call(zs,"CanBurst"),"grounded non-contest ball is eligible");var probe=ball.gameObject.AddComponent<NewShotContactProbe>();probe.owner=zs;yield return Tap(zhao);yield return new WaitForSeconds(.1f);yield return Tap(zhao);Check((float)Field(zs,"kickUntil")>Time.time,"ground shot is armed by two native key-downs before contact");ball.position=new Vector2(zb.position.x-.65f,-1.55f);ball.velocity=Vector2.zero;Physics2D.SyncTransforms();for(int i=0;i<24&&Fx(zs,4)<0;i++)yield return new WaitForFixedUpdate();Check(probe.accepted,"ground shot has genuine instep contact");Check(Fx(zs,4)>=0,"ground burst still triggers on real ground shot");Check(ball.velocity.x<-12&&ball.velocity.y<1,"ground burst remains fast and low");}
 bool GroundContact(){ContactPoint2D[] contacts=new ContactPoint2D[16];int mask=(int)(LayerMask)pt.GetField("ground").GetValue(fan);foreach(Collider2D c in fan.GetComponentsInChildren<Collider2D>()){int count=c.GetContacts(contacts);for(int i=0;i<count;i++){var p=contacts[i];Collider2D other=p.collider==c?p.otherCollider:p.collider;if(other!=null&&!other.isTrigger&&other.transform.root.name!="Fan"&&other.transform.root.name!="Zhao"&&other!=ball.GetComponent<Collider2D>()&&(mask&(1<<other.gameObject.layer))!=0&&p.point.y<fb.position.y-.2f)return true;}}return false;}
 void Capture(string label){if(SystemInfo.graphicsDeviceType==UnityEngine.Rendering.GraphicsDeviceType.Null)return;Camera cam=Camera.main;var prior=cam.targetTexture;var active=RenderTexture.active;var rt=new RenderTexture(1024,768,24);cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var png=new Texture2D(1024,768,TextureFormat.RGB24,false);png.ReadPixels(new Rect(0,0,1024,768),0,0);png.Apply();System.IO.File.WriteAllBytes(System.IO.Path.GetFullPath(System.IO.Path.Combine(Application.dataPath,"../../new-drop-"+label+".png")),png.EncodeToPNG());cam.targetTexture=prior;RenderTexture.active=active;rt.Release();Destroy(rt);Destroy(png);}
 IEnumerator Drop(bool skills,bool rear=false,bool rising=true){yield return Scene(skills);Move(fan,fb,new Vector2(-2,2.1f));fa.SetTrigger("Jump");foreach(var b in fan.GetComponentsInChildren<Rigidbody2D>())b.velocity=new Vector2(0,rising?3f:-1f);ball.position=new Vector2(rear?-5:3,40);for(int i=0;i<3;i++)yield return new WaitForFixedUpdate();float start=Time.time,landing=-10,maxError=0,minVy=0,gravity=fb.gravityScale;DownPulse=true;bool captured=false;for(int i=0;i<90;i++){yield return new WaitForFixedUpdate();maxError=Mathf.Max(maxError,Joints(fan));minVy=Mathf.Min(minVy,fb.velocity.y);if(!captured&&skills&&Time.time-start>.12f){captured=true;Capture(rear?"rear":"front");}if(GroundContact()&&landing<0)landing=Time.time-start;}
  Debug.Log("NEW DROP skills="+skills+" rear="+rear+" rising="+rising+" landing="+landing+" minVy="+minVy+" joint="+maxError);
  Check(landing>0,"player lands through genuine ground collision");Check(Mathf.Abs(fb.gravityScale-gravity)<.001f,"drop leaves original gravity scale intact");Check(fan.GetComponentsInChildren<Joint2D>().Length==9,"drop retains all 9 native joints");if(!skills){classicLanding=landing;Check(fs==null,"classic creates no drop skill");}else{Check(Fx(fs,9)>=0,"S triggers down skill air rear="+rear);Check(landing<classicLanding*.75f&&landing<.7f,"drop lands substantially sooner than ordinary fall");Check(minVy<-6&&minVy>-10,"rapid descent is bounded");Check(!(bool)Field(fs,"quickDrop"),"drop ends automatically on landing");Check(maxError<.3f,"accelerated descent and landing keep limbs joined");}
 }
 IEnumerator Guards(){yield return Scene(true);DownPulse=true;for(int i=0;i<3;i++)yield return new WaitForFixedUpdate();Check(Fx(fs,9)<0,"S on ground does not trigger");ball.position=new Vector2(zb.position.x+3,1);PlayerSkills.SetAction(za,"Kick",zhao);yield return new WaitForSeconds(.12f);Check(Mathf.Abs(za.speed-1)<.01f&&Fx(zs,8)<0,"rear ball retains prior shooting skill restriction");yield return Scene(true);PlayerSkills.SetAction(za,"Kick",zhao);yield return new WaitForSeconds(.08f);Check(Mathf.Abs(za.speed-1.25f)<.01f,"pause check observes active quicker shot");Time.timeScale=0;yield return null;yield return null;Check(Mathf.Abs(za.speed-1)<.01f,"pausing restores quicker shot animation rate");Time.timeScale=1;yield return Scene(true);Move(fan,fb,new Vector2(-2,2.1f));foreach(var b in fan.GetComponentsInChildren<Rigidbody2D>())b.velocity=Vector2.up;for(int i=0;i<3;i++)yield return new WaitForFixedUpdate();DownPulse=true;for(int i=0;i<2;i++)yield return new WaitForFixedUpdate();Check((bool)Field(fs,"quickDrop"),"reset check observes active drop");PlayerSkills.ResetAll();Check(!(bool)Field(fs,"quickDrop")&&Fx(fs,9)<0,"round reset clears drop state and animation");}
 IEnumerator AIChoice(){yield return Scene(true);typeof(GameAIMod).GetField("mode",BindingFlags.NonPublic|BindingFlags.Static).SetValue(null,2);Move(fan,fb,new Vector2(-2,2.1f));foreach(var b in fan.GetComponentsInChildren<Rigidbody2D>())b.velocity=Vector2.down;ball.position=new Vector2(-2,-1.55f);for(int i=0;i<3;i++)yield return new WaitForFixedUpdate();object state=typeof(GameAIMod).GetMethod("GetState",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{fan});state.GetType().GetField("serveApproach").SetValue(state,false);state.GetType().GetField("frame").SetValue(state,-1);typeof(GameAIMod).GetMethod("UpdateDecision",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new[]{(object)fan,state});Check((bool)state.GetType().GetField("down").GetValue(state),"Fan AI requests down command for reachable ball below");}
