 void Touch(PlayerSkills s,bool sole=false,bool knee=false){BoxCollider2D limb=s.transform.Find("R_LowLeg").GetComponent<BoxCollider2D>();Vector2 cp=limb.transform.TransformPoint(limb.offset+new Vector2(sole?0:limb.size.x*.5f,limb.size.y*(sole?-.5f:knee?.35f:-.3f)));Vector2 n=limb.transform.TransformDirection(sole?Vector2.down:Vector2.right);Call(s,s==fs?"VolleyOnContact":"BurstOnContact",limb,cp,n);}
 IEnumerator DoubleGuards(bool isFan){yield return Scene(true);PlayerSkills s=isFan?fs:zs;Component player=isFan?fan:zhao;int skill=isFan?5:4;ball.position=new Vector2(0,1);ball.velocity=Vector2.zero;
