 IEnumerator FanAirShot(){yield return Scene(true);pt.GetField("doJump").SetValue(fan,true);PlayerSkills.SetAction(fa,"Jump",fan);yield return Tap(fan);yield return new WaitForSeconds(.1f);yield return Tap(fan);yield return new WaitForSeconds(.2f);float radius=ball.GetComponent<CircleCollider2D>().radius*Mathf.Abs(ball.transform.lossyScale.x),best=float.NegativeInfinity;BoxCollider2D limb=null;Vector2 point=Vector2.zero,n=Vector2.zero,pos=Vector2.zero;foreach(string name in new[]{"L_LowLeg","R_LowLeg"}){var c=fan.transform.Find(name).GetComponent<BoxCollider2D>();foreach(float side in new[]{-1f,1f}){Vector2 cp=c.transform.TransformPoint(c.offset+new Vector2(side*c.size.x*.5f,-c.size.y*.3f));Vector2 cn=c.transform.TransformDirection(Vector2.right*side);Vector2 candidate=cp+cn*radius*.85f;if(candidate.x>best){best=candidate.x;limb=c;point=cp;n=cn;pos=candidate;}}}ball.position=pos;ball.velocity=limb.attachedRigidbody.GetPointVelocity(point)-n*2;Physics2D.SyncTransforms();var probe=ball.gameObject.AddComponent<NewShotContactProbe>();probe.owner=fs;for(int i=0;i<5;i++)yield return new WaitForFixedUpdate();Check(probe.accepted,"Fan jumping shot makes real instep contact");Check(Fx(fs,5)>=0,"Fan native double tap triggers real aerial volley");Check(ball.velocity.y>5,"Fan volley preserves high arcing trajectory");}
