 IEnumerator Rules(){Component panel=FindObjectOfType(Type.GetType("MainPanel, Assembly-CSharp")) as Component;UnityEngine.UI.Button teach=null;foreach(var b in panel.GetComponentsInChildren<UnityEngine.UI.Button>(true))if(b.name=="btn_Teach")teach=b;teach.onClick.Invoke();yield return new WaitForSeconds(.15f);Component rules=FindObjectOfType(Type.GetType("TeachPanel, Assembly-CSharp")) as Component;Check(rules!=null,"original main-screen rules button opens original panel");UnityEngine.UI.Text text=null;foreach(var t in rules.GetComponentsInChildren<UnityEngine.UI.Text>(true))if(t.name=="text")text=t;Check(text!=null&&text.text.Contains("头球：J（经典模式也可使用）"),"original rules include classic J header");Check(text.text.Contains("在特技模式下连按两下射门键，有奇效！"),"rules use exact requested hint");Check(!text.text.Contains("掠地瞬击")&&!text.text.Contains("弧线落叶"),"rules omit special skill descriptions");
  foreach(int width in new[]{800,1280}){Screen.SetResolution(width,width==800?480:720,false);yield return new WaitForSeconds(.2f);Canvas.ForceUpdateCanvases();Check(text.cachedTextGenerator.characterCountVisible>=text.text.Length-2,"all rules characters fit at width="+width);Debug.Log("RULE LAYOUT "+width+" rect="+text.rectTransform.rect+" font="+text.cachedTextGenerator.fontSizeUsedForBestFit+" chars="+text.cachedTextGenerator.characterCountVisible+" len="+text.text.Length);CaptureRules(width);}
