 void CaptureRules(int width){if(SystemInfo.graphicsDeviceType==UnityEngine.Rendering.GraphicsDeviceType.Null)return;Camera cam=Camera.main;bool created=cam==null;if(created){cam=new GameObject("Rules Capture Camera").AddComponent<Camera>();cam.orthographic=true;cam.orthographicSize=5;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=Color.black;}var rt=new RenderTexture(width,width==800?480:720,24);var oldTarget=cam.targetTexture;var oldActive=RenderTexture.active;var canvas=FindObjectOfType(Type.GetType("TeachPanel, Assembly-CSharp")) as Component;Canvas c=canvas.GetComponentInParent<Canvas>();var oldMode=c.renderMode;var oldCamera=c.worldCamera;var oldDistance=c.planeDistance;c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=cam;c.planeDistance=5;cam.targetTexture=rt;Canvas.ForceUpdateCanvases();cam.Render();RenderTexture.active=rt;var png=new Texture2D(rt.width,rt.height,TextureFormat.RGB24,false);png.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);png.Apply();System.IO.File.WriteAllBytes(System.IO.Path.GetFullPath(System.IO.Path.Combine(Application.dataPath,"../../double-rules-"+width+".png")),png.EncodeToPNG());c.renderMode=oldMode;c.worldCamera=oldCamera;c.planeDistance=oldDistance;cam.targetTexture=oldTarget;RenderTexture.active=oldActive;rt.Release();Destroy(rt);Destroy(png);if(created)Destroy(cam.gameObject);}
