 IEnumerator Start(){Application.targetFrameRate=60;Application.runInBackground=true;QualitySettings.vSyncCount=0;AudioListener.volume=0;yield return new WaitForSeconds(.2f);yield return Rules();yield return DoubleGuards(true);yield return DoubleGuards(false);yield return FanAirShot();yield return ClassicDouble();yield return Shot(false);yield return Shot(true);Check(quickKick<classicKick*.9f&&quickKick>classicKick*.65f,"native shot duration reflects 25 percent swing-speed boost classic="+classicKick+" quick="+quickKick);yield return Shot(true,true);yield return AirShot();yield return GroundShot();yield return Drop(false);yield return Drop(true);yield return Drop(true,true);yield return Drop(true,false,false);yield return Guards();yield return AIChoice();yield return AIShots();Debug.Log("DOUBLE SHOT COMPLETE checks="+checks+" failures="+failures);Application.Quit();}
